import React, { useEffect, useRef, useState } from 'react';
import { createRoot } from 'react-dom/client';
import { Shield, ShieldCheck, ScanLine, History, BookOpen, Settings2, ArrowUpLeft, ArrowLeft, Link2, Clipboard, Check, ChevronLeft, ChevronDown, Bell, CircleHelp, Gamepad2, Menu, X, Globe2, FileSearch, LockKeyhole, ExternalLink, LoaderCircle, CircleAlert, Search, Download, Trash2, CheckCheck, Sparkles, Info, Zap, Server, Copy, UserRound } from 'lucide-react';
import './styles.css';
import { readHistory } from './history.js';
import { apiUrl } from './api.js';
import {sendEmailCode,checkAccountAvailability,verifyEmailCode,signInWithPassword,completeGoogleSignup,readEmailSession} from './email-account.js';
import { localizeDocument } from './locale.js';

if (import.meta.env.PROD && 'serviceWorker' in navigator) {
  window.addEventListener('load',()=>navigator.serviceWorker.register(`${import.meta.env.BASE_URL}sw.js`).catch(()=>{}),{once:true});
}

const fa = v => new Intl.NumberFormat(document.documentElement.lang==='fa'?'fa-IR':'en-US').format(v);
const date = v => new Intl.DateTimeFormat(document.documentElement.lang==='fa'?'fa-IR':'en-US', { day:'numeric', month:'long', hour:'2-digit', minute:'2-digit' }).format(new Date(v));
const labels = { limited: 'تهدید شناخته‌شده‌ای مشاهده نشد', warning: 'نیازمند احتیاط', danger: 'تهدید گزارش‌شده', unavailable: 'بررسی ناقص', unscanned: 'بررسی نشده', skipped: 'بررسی نشده',queued:'در صف',blocked:'آدرس مسدود',requires_access:'نیازمند دسترسی',requires_payment:'نیازمند پرداخت',budget_exceeded:'سقف بررسی' };
const descriptions = { limited: 'در صفحه‌های عمومی و استعلام‌های موفق، تهدید شناخته‌شده‌ای مشاهده نشد.', warning: 'نشانه‌هایی پیدا شد که نیاز به بررسی بیشتر دارند.', danger: 'این لینک یا فایل در پایگاه تهدید گزارش شده است.', unavailable:'بررسی کامل نشد؛ امنیت موارد نامشخص تأیید نمی‌شود.' };
const STORAGE_KEY = 'gamescam-guard-history-v1';

function ShieldArt({ busy = false }) {
  return <div className={`shield-art ${busy ? 'busy' : ''}`} aria-hidden="true">
    <div className="radar-ring ring-1"/><div className="radar-ring ring-2"/><div className="radar-ring ring-3"/><div className="radar-axis axis-h"/><div className="radar-axis axis-v"/>
    <span className="radar-dot dot-1"/><span className="radar-dot dot-2"/><span className="radar-dot dot-3"/>
    <span className="art-cross cross-1">+</span><span className="art-cross cross-2">+</span>
    <div className="floating-tag tag-lock"><LockKeyhole size={15}/><span>SSL</span></div>
    <div className="floating-tag tag-hash"><Globe2 size={17}/><span>PUBLIC WEB</span></div>
    <svg className="big-shield" width="156" height="170" viewBox="0 0 156 170" fill="none">
      <defs><linearGradient id="shieldFill" x1="40" y1="15" x2="115" y2="153" gradientUnits="userSpaceOnUse"><stop stopColor="#e6ffc9"/><stop offset="1" stopColor="#a9e777"/></linearGradient><linearGradient id="shieldEdge" x1="0" y1="0" x2="156" y2="170"><stop stopColor="#fff"/><stop offset="1" stopColor="#57ad6c"/></linearGradient><filter id="shadow"><feDropShadow dx="0" dy="9" stdDeviation="8" floodColor="#336e49" floodOpacity=".17"/></filter></defs>
      <path d="M78 10C57 23 38 29 18 34V77C18 116 44 142 78 160C112 142 138 116 138 77V34C118 29 99 23 78 10Z" fill="url(#shieldFill)" stroke="url(#shieldEdge)" strokeWidth="2" filter="url(#shadow)"/>
      <path d="M78 25C60 35 45 40 32 44V78C32 107 49 127 78 145C107 127 124 107 124 78V44C111 40 96 35 78 25Z" stroke="#fafff4" strokeWidth="1.5"/>
      <path d="m52 81 18 18 36-38" stroke="#245c3b" strokeWidth="8" strokeLinecap="round" strokeLinejoin="round"/>
      <path d="M24 43v29" stroke="white" strokeWidth="3" strokeLinecap="round" opacity=".65"/>
    </svg>
  </div>;
}

function App() {
  const [locale,setLocale]=useState(()=>{try{return localStorage.getItem('guard-locale-v2')==='fa'?'fa':'en';}catch{return 'en';}});
  const localeLoaded=useRef(false);
  const [account,setAccount]=useState(null);
  const [accountState,setAccountState]=useState('loading');
  const [accountRetry,setAccountRetry]=useState(0);
  const [googleEnabled,setGoogleEnabled]=useState(false);
  const [googleSignup,setGoogleSignup]=useState('');
  const [page, setPage] = useState('scan');
  const [url, setUrl] = useState('');
  const [mode, setMode] = useState('basic');
  const [browserMode, setBrowserMode] = useState('isolated');
  const [busy, setBusy] = useState(false);
  const [advancedBusy, setAdvancedBusy] = useState(false);
  const [scanEvents,setScanEvents]=useState([]);
  const [liveBrowserUrl,setLiveBrowserUrl]=useState('');
  const [pendingJob,setPendingJob]=useState(()=>{try{if(localStorage.getItem('guard-save-history')==='false')return null;const saved=JSON.parse(localStorage.getItem('guard-pending-job')||'null');return saved&&typeof saved.id==='string'&&typeof saved.token==='string'&&saved.token.length<1500*1024&&saved.mode==='advanced'&&Number.isInteger(saved.next)&&Number.isInteger(saved.total)?saved:null;}catch{return null;}});
  const scanAbort=useRef(null);
  const [result, setResult] = useState(null);
  const [error, setError] = useState('');
  const [toast, setToast] = useState('');
  const [modal, setModal] = useState(null);
  const [mobileNav, setMobileNav] = useState(false);
  const [health, setHealth] = useState(null);
  const [search, setSearch] = useState('');
  const [filter, setFilter] = useState('all');
  const [notifications, setNotifications] = useState(false);
  const [saveHistory, setSaveHistory] = useState(()=> { try { return localStorage.getItem('guard-save-history') !== 'false'; } catch { return false; } });
  const saveHistoryRef=useRef(saveHistory);saveHistoryRef.current=saveHistory;
  const [history, setHistory] = useState(()=> { try { return readHistory(localStorage.getItem(STORAGE_KEY)); } catch { return []; } });
  const inputRef = useRef(null); const reportRef = useRef(null); const modalRef = useRef(null); const priorFocus = useRef(null);
  useEffect(()=> { fetch(apiUrl('health')).then(r=>r.json()).then(setHealth).catch(()=>setHealth({status:'unavailable'})); }, []);
  useEffect(()=>{let disposed=false;setAccount(null);setAccountState('loading');(async()=>{try{const response=await fetch(apiUrl('auth/status'));const config=await response.json();if(!response.ok||!config.configured)throw new Error('email_auth_unavailable');if(!disposed)setGoogleEnabled(config.google?.configured===true);const fragment=new URLSearchParams(window.location.hash.slice(1)),callbackToken=fragment.get('guard-session'),signupToken=fragment.get('guard-google-signup'),callbackError=fragment.get('guard-auth-error');if(callbackToken||signupToken||callbackError)history.replaceState(null,'',window.location.pathname+window.location.search);if(callbackError&&!disposed)setToast(callbackError);if(signupToken&&!disposed){setGoogleSignup(signupToken);setModal('account');}const token=callbackToken||localStorage.getItem('guard-account-session');if(token){try{const profile=await readEmailSession(token);localStorage.setItem('guard-account-session',token);if(!disposed)setAccount({...profile,sessionToken:token});}catch{localStorage.removeItem('guard-account-session');}}if(!disposed)setAccountState('ready');}catch{if(!disposed)setAccountState('unavailable');}})();return()=>{disposed=true;};},[accountRetry]);
  useEffect(()=>{try{localStorage.setItem('guard-locale-v2',locale);localStorage.removeItem('guard-locale');}catch{};localeLoaded.current=true;localizeDocument(locale);},[locale]);
  useEffect(()=> { if (!toast) return; const t = setTimeout(()=>setToast(''),3500); return ()=>clearTimeout(t); }, [toast]);
  useEffect(()=> { try { localStorage.setItem('guard-save-history', String(saveHistory)); if (saveHistory) localStorage.setItem(STORAGE_KEY, JSON.stringify(history)); else {localStorage.removeItem(STORAGE_KEY);localStorage.removeItem('guard-pending-job');} } catch { /* Browser storage may be unavailable. */ } }, [history, saveHistory]);
  useEffect(()=> {
    if (!modal) return;
    priorFocus.current = document.activeElement;
    modalRef.current?.querySelector('button')?.focus();
    const listener = e => {
      if (e.key === 'Escape') setModal(null);
      if (e.key === 'Tab') {
        const nodes = modalRef.current?.querySelectorAll('button:not(:disabled),a[href],input');
        if (!nodes?.length) return;
        if (e.shiftKey && document.activeElement === nodes[0]) { e.preventDefault(); nodes[nodes.length-1].focus(); }
        else if (!e.shiftKey && document.activeElement === nodes[nodes.length-1]) { e.preventDefault(); nodes[0].focus(); }
      }
    };
    document.addEventListener('keydown',listener);
    return ()=> { document.removeEventListener('keydown',listener); priorFocus.current?.focus(); };
  }, [modal]);

  function navigate(next) { setPage(next); setMobileNav(false); setError(''); window.scrollTo({top:0,behavior:'smooth'}); }
  function remember(data) {
    // Keep evidence locally, but avoid storing screenshots or filling browser storage.
    const saved = {...data, preview:data.preview ? {status:data.preview.status,detail:data.preview.detail} : undefined, remote:undefined};
    setHistory(previous=>readHistory(JSON.stringify([saved,...previous.filter(h=>h.id !== data.id)])));
  }
  async function callApi(endpoint, body) {
    let response;
    try { response = await fetch(apiUrl(endpoint), {method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}); }
    catch { throw new Error('اتصال به سرویس بررسی برقرار نشد. اتصال اینترنت را بررسی و دوباره تلاش کنید.'); }
    let data; try { data = await response.json(); } catch { throw new Error('سرویس بررسی در دسترس نیست. دوباره تلاش کنید.'); }
    if (!response.ok) throw new Error(data.error || 'بررسی انجام نشد.');
    return data;
  }
  async function callLiveScan(body) {
    let response;
    try { response=await fetch(apiUrl('scan/live'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}); }
    catch { throw new Error('اتصال به سرویس بررسی برقرار نشد. اتصال اینترنت را بررسی و دوباره تلاش کنید.'); }
    if(!response.ok){let data={};try{data=await response.json();}catch{}throw new Error(data.error||'بررسی انجام نشد.');}
    if(!response.body)throw new Error('نمای زندهٔ بررسی در این مرورگر در دسترس نیست.');
    const reader=response.body.getReader(),decoder=new TextDecoder();let text='',result;
    const line=value=>{if(!value.trim())return;const data=JSON.parse(value);if(data.error)throw new Error(data.error);if(data.event){setScanEvents(events=>[...events,data.event].slice(-8));if(typeof data.event.liveUrl==='string')setLiveBrowserUrl(data.event.liveUrl);}if(data.result)result=data.result;};
    for(;;){const {done,value}=await reader.read();if(done)break;text+=decoder.decode(value,{stream:true});let index;while((index=text.indexOf('\n'))!==-1){line(text.slice(0,index));text=text.slice(index+1);}}
    text+=decoder.decode();if(text.trim())line(text);if(!result)throw new Error('پاسخ کامل بررسی دریافت نشد.');return result;
  }
  async function runScan(event, link = url) {
    event?.preventDefault(); if (busy || advancedBusy) return;
    if (!link.trim()) { setError('اول لینک سایت را وارد کنید.'); inputRef.current?.focus(); return; }
    setBusy(true); setError(''); setResult(null);setScanEvents([]);setLiveBrowserUrl('');
    try {
      const data = await callLiveScan({url:link.trim(),mode,browserMode}); setResult(data); setUrl(data.url); remember(data); setNotifications(true);
      if(data.inputAdjusted)setToast('نشانهٔ اضافی متن کپی‌شده از ابتدا یا انتهای لینک حذف شد.');
      setTimeout(()=>reportRef.current?.scrollIntoView({behavior:'smooth',block:'start'}),100);
      if (mode === 'advanced' && data.linkInventory?.links?.some(link=>link.kind==='page')) setModal('advanced');
    } catch (e) { setError(e.message); }
    finally { setBusy(false); }
  }
  async function runAdvanced() {
    if (!result || advancedBusy) return; setModal(null); setAdvancedBusy(true); setError('');setScanEvents([]);
    try {const job=await callApi('jobs/start',{id:result.id,token:result.scanToken,mode:'advanced',consent:true});await continueQueue(job);}
    catch (e) { setError(e.name==='AbortError'?'صف متوقف شد؛ از آخرین دسته می‌توانید ادامه دهید.':e instanceof TypeError?'اتصال به سرویس قطع شد؛ ادامهٔ صف محفوظ است.':e.message); }
    finally { setAdvancedBusy(false);scanAbort.current=null; }
  }
  function saveQueue(job){
    const saved={id:job.id,token:job.token,mode:job.mode,next:job.next,total:job.targets?.length||job.total||0};setPendingJob(saved);
    if(saveHistoryRef.current)try{localStorage.setItem('guard-pending-job',JSON.stringify(saved));}catch{setToast('ذخیرهٔ ادامهٔ صف در مرورگر ممکن نشد؛ صفحه را باز نگه دارید.');}
  }
  async function continueQueue(first){
    let job=first;saveQueue(job);
    for(;;){
      const controller=new AbortController();scanAbort.current=controller;
      const response=await fetch(apiUrl('jobs/step'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:job.id,token:job.token}),signal:controller.signal});
      if(!response.ok){const data=await response.json();throw new Error(data.error||'این دسته بررسی نشد؛ ادامهٔ صف محفوظ است.');}
      const reader=response.body.getReader(),decoder=new TextDecoder();let text='',completed;
      const line=value=>{if(!value.trim())return;const data=JSON.parse(value);if(data.error)throw new Error(data.error);if(data.event)setScanEvents(events=>[...events,data.event].slice(-12));if(data.job)completed=data;};
      for(;;){const {done,value}=await reader.read();if(done)break;text+=decoder.decode(value,{stream:true});let index;while((index=text.indexOf('\n'))!==-1){line(text.slice(0,index));text=text.slice(index+1);}}
      text+=decoder.decode();if(text.trim())line(text);
      if(!completed)throw new Error('پاسخ کامل دسته دریافت نشد؛ از آخرین دستهٔ ذخیره‌شده ادامه دهید.');
      job=completed.job;saveQueue(job);
      if(job.done){setResult(completed.report);remember(completed.report);setPendingJob(null);localStorage.removeItem('guard-pending-job');setToast('گزارش مقصدهای صف آماده شد.');break;}
    }
    scanAbort.current=null;
  }
  async function resumeQueue(){if(!pendingJob||advancedBusy)return;setMode(pendingJob.mode);setAdvancedBusy(true);setError('');try{await continueQueue(pendingJob);}catch(e){setError(e.name==='AbortError'?'صف متوقف شد؛ می‌توانید از آخرین دسته ادامه دهید.':e instanceof TypeError?'اتصال به سرویس قطع شد؛ ادامهٔ صف محفوظ است.':e.message);}finally{setAdvancedBusy(false);scanAbort.current=null;}}
  async function paste() {
    try { const value = await navigator.clipboard.readText(); setUrl(value.trim()); setError(''); inputRef.current?.focus(); }
    catch { setToast('برای چسباندن لینک از Ctrl+V یا گزینهٔ چسباندن گوشی استفاده کنید.'); inputRef.current?.focus(); }
  }
  function exportReport() {
    const file = new Blob([JSON.stringify(result,null,2)], {type:'application/json;charset=utf-8'});
    const href = URL.createObjectURL(file); const a = document.createElement('a'); a.href=href; a.download=`gamescam-guard-${result.domain}.json`; a.click(); URL.revokeObjectURL(href); setToast('گزارش ذخیره شد.');
  }
  const filteredHistory = history.filter(h=>(h.domain.toLowerCase().includes(search.toLowerCase()) || h.title.toLowerCase().includes(search.toLowerCase())) && (filter==='all' || h.status===filter));
  const pageUnavailable = result?.pageFetch?.status === 'unavailable';
  const fileExcluded = result?.fileScanExcluded === true;
  const navItems = [{id:'scan',label:'بررسی لینک',icon:ScanLine},{id:'history',label:'تاریخچه بررسی‌ها',icon:History},{id:'guide',label:'چطور کار می‌کند؟',icon:BookOpen}];

  function HistoryTable({ compact = false }) {
    const rows = compact ? history.slice(0,3) : filteredHistory;
    return <div className="history-table">
      <div className="table-row table-heading"><span>وب‌سایت</span><span>وضعیت بررسی</span><span>زمان بررسی</span><span/></div>
      {!rows.length ? <div className="empty-history"><div className="empty-icon"><History size={24}/></div><div><strong>{history.length ? 'نتیجه‌ای پیدا نشد' : 'اولین بررسی‌ات از اینجا شروع می‌شود'}</strong><p>{history.length ? 'عبارت جستجو یا فیلتر را تغییر بده.' : 'بعد از بررسی یک لینک، گزارش آن را اینجا می‌بینی.'}</p></div>{!compact && !history.length && <button className="text-button" onClick={()=>navigate('scan')}>بررسی اولین لینک <ArrowLeft size={16}/></button>}</div> : rows.map(item=><button key={item.id} className="table-row history-row" onClick={()=>{setResult(item);setUrl(item.url);navigate('scan');setTimeout(()=>reportRef.current?.scrollIntoView({behavior:'smooth'}),100);}}><span className="website-cell"><span className="website-icon"><Globe2 size={17}/></span><span><b dir="ltr">{item.domain}</b><small>{item.advanced?'Advanced website scan':'Website scan'}</small></span></span><span><span className={`status-badge ${item.status}`}><i/>{labels[item.status]}</span></span><span className="date-cell">{date(item.createdAt)}</span><ChevronLeft size={17}/></button>)}
    </div>;
  }

  return <div className="app-shell">
    {mobileNav && <div className="nav-backdrop" onClick={()=>setMobileNav(false)}/>}
    <aside className={`sidebar ${mobileNav?'open':''}`}>
      <a className="brand" href="#" onClick={e=>{e.preventDefault();navigate('scan');}}><span className="brand-symbol"><ShieldCheck size={27} strokeWidth={1.8}/></span><span><strong>گیم‌اسکم گارد<span className="brand-dot">.</span></strong><small>GAMESCAM GUARD</small></span></a>
      <div className="sidebar-label">فضای کار شما</div>
      <nav>{navItems.map(item=><button key={item.id} className={`nav-item ${page===item.id?'active':''}`} onClick={()=>navigate(item.id)}><item.icon size={20}/><span>{item.label}</span>{item.id==='scan' && <span className="nav-active-dot"/>}{item.id==='history' && history.length>0 && <small>{fa(history.length)}</small>}</button>)}</nav>
      <div className="sidebar-separator"/>
      <div className="sidebar-label">بیشتر بدانید</div>
      <button className={`nav-item ${page==='resources'?'active':''}`} onClick={()=>navigate('resources')}><Shield size={20}/><span>راهنمای بازی امن</span><ArrowUpLeft size={16}/></button>
      <button className={`nav-item ${page==='settings'?'active':''}`} onClick={()=>navigate('settings')}><Settings2 size={20}/><span>تنظیمات</span></button>
      <div className="sidebar-bottom"><div className="sidebar-tip"><div className="tip-mini-icon"><Gamepad2 size={24}/><Sparkles size={12}/></div><strong>بازی کن، با خیال راحت‌تر.</strong><p>قبل از دانلود یا خرید،<br/>یک قدم برای امنیتت بردار.</p><button onClick={()=>navigate('resources')}>راهنمای گیمرها <ArrowLeft size={16}/></button></div><div className="sidebar-service"><span className={`service-dot ${health?.status==='ok'?'':'offline'}`}/><span>{health?.status==='ok'?'سرویس بررسی فعال است':health?'سرویس در دسترس نیست':'در حال اتصال به سرویس'}</span><small>v1.0</small></div></div>
    </aside>

    <div className="main-shell">
      <header className="topbar"><div className="breadcrumb"><button className="icon-button mobile-menu" aria-label="باز کردن منو" onClick={()=>setMobileNav(true)}><Menu size={21}/></button><span>فضای کار</span><ChevronLeft size={14}/><b>{{scan:'بررسی لینک',history:'تاریخچه بررسی‌ها',guide:'چطور کار می‌کند؟',resources:'راهنمای بازی امن',settings:'تنظیمات'}[page]}</b></div><div className="header-actions"><button className="locale-button" aria-label="تغییر زبان" onClick={()=>setLocale(current=>current==='en'?'fa':'en')}><Globe2 size={17}/><span>{locale==='en'?'FA':'EN'}</span></button><button className="icon-button" aria-label="راهنما" onClick={()=>setModal('help')}><CircleHelp size={20}/></button><div className="notification-wrap"><button className="icon-button" aria-label="اعلان‌ها" onClick={()=>{setModal('notifications');setNotifications(false);}}><Bell size={20}/>{notifications && <i className="notification-dot"/>}</button></div><div className="header-divider"/><button className="profile-button" aria-label="Sign in or manage account" onClick={()=>setModal('account')}><span className="profile-avatar">{account?(account.firstName?.slice(0,1)||account.username?.slice(0,1)||account.email?.slice(0,1)||'?').toUpperCase():<UserRound size={16} aria-hidden="true"/>}</span><span className="profile-name">{account?.firstName||account?.username||account?.email||'Gamer'}<small>{account?'Personal space':'Sign in · Sign up'}</small></span></button></div></header>
      <main>
        {page==='scan' && <>
          <section className="hero"><div className="hero-copy"><div className="eyebrow"><span/>یک قدم جلوتر از کلاهبردارها</div><h1>قبل از کلیک، <span>مطمئن شو.</span></h1><p>لینک بازی، ماد یا فروشگاه را بررسی کن.<br className="mobile-break"/> ما نشانه‌های خطر را قبل از تو پیدا می‌کنیم.</p></div><div className="hero-stamp"><ShieldCheck size={18}/><span>برای گیمرها،<br/><b>با فکر امنیت</b></span><span className="stamp-orbit"/></div></section>
          <section className="scan-workspace">
            <div className="scan-card">
              <div className="scan-tabs" role="tablist" aria-label="Scan type"><button role="tab" aria-selected={mode==='basic'} className={mode==='basic'?'selected':''} onClick={()=>setMode('basic')} disabled={busy||advancedBusy}><Link2 size={18}/>Website scan</button><button role="tab" aria-selected={mode==='advanced'} className={mode==='advanced'?'selected':''} onClick={()=>setMode('advanced')} disabled={busy||advancedBusy}><Globe2 size={18}/>Advanced website scan<span className="tiny-tag">public pages</span></button></div>
              <form onSubmit={runScan} className="scan-form"><div className="form-title"><div><h2>Is this website trustworthy?</h2><p>{mode==='basic'?'Enter a public website address to start a passive scan.':'After your confirmation, public website pages found on this site are scanned in bounded batches.'}</p></div><span className="form-icon"><ScanLine size={23}/></span></div><label htmlFor="site-url">لینک وب‌سایت</label><div className={`url-input-wrap ${error?'invalid':''}`}><Link2 size={19}/><input ref={inputRef} id="site-url" type="text" inputMode="url" dir="ltr" autoComplete="url" spellCheck="false" placeholder="https://example.com" value={url} onChange={e=>{setUrl(e.target.value);setError('');}} disabled={busy||advancedBusy} aria-describedby={error?'scan-error':undefined}/><button type="button" className="paste-button" onClick={paste} disabled={busy||advancedBusy}><Clipboard size={15}/><span>چسباندن</span></button></div><div className="input-hint"><LockKeyhole size={12}/><span>لینک روی سرور بررسی می‌شود؛ در دستگاهت باز نمی‌شود.</span></div>{mode==='advanced'&&<div className="browser-source"><label htmlFor="browser-source">منبع شواهد پیشرفته</label><select id="browser-source" value={browserMode} onChange={event=>setBrowserMode(event.target.value)} disabled={busy||advancedBusy}><option value="isolated">مرورگر ایزولهٔ داخلی — تصویر امن</option>{health?.providers?.browserbase&&<option value="browserbase">Browserbase Live — نمایش زندهٔ فقط‌خواندنی</option>}{health?.providers?.tinyfish&&<option value="tinyfish">TinyFish Fetch — متن عمومی، بدون نمایش زنده</option>}</select><small>فقط پس از نبودن تهدید شناخته‌شده اجرا می‌شود؛ ورود، پرداخت، بارگذاری و دانلود مسدود هستند.</small></div>}<div className="scan-action"><button className="primary-button scan-submit" disabled={busy||advancedBusy}>{busy?<LoaderCircle size={19} className="spin"/>:<ScanLine size={19}/>}<span>{busy?'در حال بررسی لینک…':'شروع بررسی'}</span>{!busy&&<ArrowLeft size={17}/>}</button><span className="scan-time"><Zap size={14}/>بدون نصب برنامه</span></div>{error && <div className="error-message" id="scan-error" role="alert"><CircleAlert size={17}/><span>{error}</span></div>}
                {busy && <div className="scan-progress live-scan" role="status"><div className="progress-bar indeterminate"><i/></div><span>درخواست بررسی سایت در حال پردازش است؛ نتیجه پس از دریافت پاسخ نمایش داده می‌شود.</span><div className="live-browser"><div className="live-browser-bar"><span/><span/><span/><b>{liveBrowserUrl?'Browserbase Live':'Isolated cloud browser'}</b></div>{liveBrowserUrl?<iframe className="live-browser-frame" title="Live public website evidence" src={liveBrowserUrl} sandbox="allow-same-origin allow-scripts" referrerPolicy="no-referrer"/>:<div className="live-browser-screen"><Globe2 size={20}/><strong>{scanEvents.at(-1)?.message||'Preparing a protected browser session'}</strong><small>Public pages only · no sign-in · no payment · no downloads · JavaScript disabled</small><ol>{scanEvents.slice(-4).map((event,index)=><li key={`${event.phase}-${index}`}>{event.message}</li>)}</ol></div>}</div></div>}
              </form><div className="scan-card-footer"><span><Check size={14}/>HTTP and HTTPS checks</span><span><Check size={14}/>No file upload or execution</span><span><Check size={14}/>Evidence-led report</span></div>
            </div>
            <div className="visual-card"><span className="visual-label"><span className={busy?'pulse':''}/>{busy?'گارد در حال بررسی است':'گارد آمادهٔ بررسی است'}</span><ShieldArt busy={busy}/><h3>یک لینک، چند لایه بررسی.</h3><p>From public page content to linked pages;<br/>each signal supports a clearer decision.</p><div className="visual-tags"><span><Globe2 size={12}/>Website</span><span><Link2 size={12}/>Public links</span><span><ShieldCheck size={12}/>Threat signals</span></div></div>
          </section>
          {!advancedBusy&&pendingJob&&<button className="outline-button" onClick={resumeQueue}>ادامهٔ صف ثبت‌شده ({fa(pendingJob.next||0)} از {fa(pendingJob.total||0)})</button>}{advancedBusy&&!result&&<div className="advanced-loading" role="status"><LoaderCircle className="spin" size={20}/>{scanEvents.at(-1)?.message||'درخواست در حال پردازش است'}</div>}
          <div className="how-strip"><div><span className="step-icon"><Link2 size={19}/></span><span><b>لینک را وارد کن</b><small>آدرس سایت یا فروشگاه بازی</small></span><em>01</em></div><ChevronLeft className="step-arrow" size={16}/><div><span className="step-icon"><ScanLine size={19}/></span><span><b>نشانه‌ها را بررسی می‌کنیم</b><small>محتوا، لینک‌ها و گزارش‌های تهدید</small></span><em>02</em></div><ChevronLeft className="step-arrow" size={16}/><div><span className="step-icon"><ShieldCheck size={19}/></span><span><b>با آگاهی تصمیم بگیر</b><small>یک گزارش شفاف، همراه با شواهد</small></span><em>03</em></div></div>

          {result && <section className="report-card" ref={reportRef}>
            <div className="section-heading"><div><span className="section-kicker">گزارش بررسی واقعی</span><h2>نتیجهٔ بررسی لینک</h2></div><button className="outline-button" onClick={exportReport}><Download size={16}/>ذخیره گزارش</button></div>
            <div className={`verdict ${result.status}`}><div className="verdict-icon">{result.status==='danger'||pageUnavailable||fileExcluded?<CircleAlert size={27}/>:result.status==='warning'?<CircleAlert size={27}/>:<ShieldCheck size={27}/>}</div><div><strong>{descriptions[result.status]}</strong><p>این نتیجه، تأیید هویت فروشنده یا تضمین امنیت کامل نیست.</p></div><span className={`status-badge ${result.status}`}><i/>{labels[result.status]}</span></div>
            <div className="report-summary"><div><small>{pageUnavailable?'Scanned address':'Observed final address'}</small><span className="report-url" dir="ltr">{result.finalUrl}</span></div><div><small>Scan time</small><b>{date(result.createdAt)}</b></div><div><small>Page links</small><b>{pageUnavailable?'Unknown':`${fa(result.linkCount)} links`}</b></div><div><small>Public page targets</small><b>{pageUnavailable?'Unknown':`${fa(result.linkInventory?.links?.filter(link=>link.kind==='page').length||0)} pages`}</b></div></div>
            {pageUnavailable&&<div className="fetch-incomplete" role="status"><CircleAlert size={21}/><div><h3>محتوای سایت مشاهده نشد</h3><p>{result.pageFetch.detail}</p><p>The number of public links is unknown. {result.pageFetch.attempts>0?`${fa(result.pageFetch.attempts)} retrieval attempts were made.`:''} Advanced website scanning needs a retrieved HTML page.</p></div>{result.status!=='danger'&&<button className="outline-button" disabled={busy||advancedBusy} onClick={event=>runScan(event,result.url)}>تلاش دوباره برای دریافت سایت <ArrowLeft size={15}/></button>}</div>}
            {result.preview?.image&&<details className="browser-preview"><summary><Globe2 size={15}/>پیش‌نمایش ایزولهٔ مرورگر ابری<span>مشاهده تصویر <ChevronDown size={13}/></span></summary><img src={result.preview.image} alt={`پیش‌نمایش محتوای عمومی ${result.domain}`} loading="lazy"/><p>{result.preview.detail} تصویر فقط برای مشاهده است؛ لینک‌ها، فرم‌ها، دانلود و درخواست‌های شبکه در محیط نمایش غیرفعال‌اند.</p></details>}
            {result.remote?.browserbase?.status==='done'&&result.remote.browserbase.liveUrl&&<details className="browser-preview remote-live" open><summary><Globe2 size={15}/>Browserbase Live<span>نمای زندهٔ فقط‌خواندنی <ChevronDown size={13}/></span></summary><iframe className="report-live-browser" title={`Live evidence for ${result.domain}`} src={result.remote.browserbase.liveUrl} sandbox="allow-same-origin allow-scripts" referrerPolicy="no-referrer"/><p>{result.remote.browserbase.detail} این پیوند کوتاه‌مدت است و پس از پایان نشست منقضی می‌شود.</p></details>}
            {result.remote?.tinyfish?.status==='done'&&<div className="browser-preview provider-evidence"><Globe2 size={15}/><div><b>TinyFish Fetch</b><p>{result.remote.tinyfish.detail}{result.remote.tinyfish.title?` عنوان مشاهده‌شده: ${result.remote.tinyfish.title}.`:''}</p></div></div>}
            {result.preview?.status==='skipped'&&<div className="browser-preview preview-pending"><Globe2 size={15}/><div><b>پیش‌نمایش مرورگر ابری</b><p>{result.preview.detail}</p></div></div>}
            {result.preview?.status==='unavailable'&&<p className="preview-unavailable"><Info size={14}/>{result.preview.detail}</p>}
            {fileExcluded&&<div className="fetch-incomplete" role="status"><Info size={21}/><div><h3>این لینک یک فایل مستقیم است</h3><p>GameScam Guard فایل را دریافت، هش، تحلیل یا اجرا نمی‌کند. برای بررسی فایل از GTA Guard استفاده کنید.</p></div></div>}
            <div className="evidence-grid"><div className="evidence-panel"><h3><Globe2 size={17}/>{pageUnavailable?'وضعیت دریافت سایت':'آنچه در سایت دیدیم'}</h3><small>{pageUnavailable?'محتوای قابل مشاهده':'عنوان صفحه'}</small><h4>{result.title}</h4>{result.description&&<p>{result.description}</p>}{result.headings.length>0&&<div className="heading-chips">{result.headings.map((h,i)=><span key={i}>{h}</span>)}</div>}{result.excerpt&&<details><summary>بخشی از متن دریافت‌شده</summary><p>{result.excerpt}</p></details>}<span className="mime-tag" dir="ltr">{result.contentType}</span></div><div className="evidence-panel"><h3><CheckCheck size={17}/>مراحل انجام‌شده</h3>{result.checks.map((c,i)=><div className="check-row" key={i}>{c.status==='done'?<Check size={16}/>:<Info size={16}/>}<div><b>{c.title}</b><small>{c.detail}</small></div></div>)}</div></div>
            {result.signals.length>0&&<div className="signals"><h3>نشانه‌های قابل توجه</h3>{result.signals.map((s,i)=><div key={i} className={`signal ${s.level}`}><CircleAlert size={17}/><div><b>{s.title}</b><p>{s.detail}</p></div></div>)}</div>}
            {result.linkInventory&&<details className="redirect-details"><summary>صفحه‌های عمومی مشاهده‌شده ({fa(result.linkInventory.links.filter(link=>link.kind==='page').length)})</summary><p>{result.linkInventory.status==='checked-targets'?'این فهرست به نتیجهٔ صف متصل است؛ وضعیت هر صفحه جداگانه ثبت شده است.':'این فهرست از HTML دریافت‌شده استخراج شده است؛ مقصد هر صفحه جداگانه باز و بررسی نشده است.'}</p>{result.linkInventory.links.filter(link=>link.kind==='page'||link.kind==='unsupported').map(link=><p key={link.position}><b>{fa(link.position)}. {link.label||'بدون عنوان'}</b> · {link.kind==='unsupported'?'غیرقابل بررسی':'لینک صفحه'} · {labels[link.status]||link.status}{link.duplicateOf?` · تکرار لینک ${fa(link.duplicateOf)}`:''}<br/>{link.url&&<span dir="ltr">{link.url}</span>}{link.reason&&<span>{link.reason}</span>}</p>)}{result.linkInventory.omitted>0&&<p>{fa(result.linkInventory.omitted)} ردیف به علت سقف اندازه یا تعداد در این فهرست نگهداری نشده است.</p>}</details>}
            {result.redirects.length>0&&<details className="redirect-details"><summary>مسیر انتقال لینک ({fa(result.redirects.length)})</summary>{result.redirects.map((r,i)=><p key={i} dir="ltr">{r.from} → {r.to} · {r.status}</p>)}</details>}
            {!result.advanced && !pageUnavailable && result.linkInventory?.links?.some(link=>link.kind==='page')&&<div className="advanced-prompt"><span className="advanced-icon"><Globe2 size={24}/></span><div><h3>Go deeper: inspect linked public pages</h3><p>Open public HTML destinations in bounded batches and record each page's evidence.</p></div><button className="primary-button" disabled={advancedBusy} onClick={()=>setModal('advanced')}>{advancedBusy?<LoaderCircle className="spin" size={17}/>:<Sparkles size={17}/>} {advancedBusy?'Scanning linked pages…':'Advanced website scan'}</button></div>}
            {advancedBusy&&<div role="status" className="advanced-loading"><LoaderCircle className="spin" size={20}/><div><b>{scanEvents.at(-1)?.message||'درخواست بررسی در حال پردازش است'}</b>{pendingJob&&<p>{fa(pendingJob.next||0)} مقصد ثبت‌شده از {fa(pendingJob.total||0)}</p>}<ul>{scanEvents.slice(-5).map((event,i)=><li key={i}>{event.message}</li>)}</ul></div>{scanAbort.current&&<button type="button" className="outline-button" onClick={()=>scanAbort.current?.abort()}>توقف صف</button>}</div>}
            {result.destinationResults&&<details className="redirect-details destination-results"><summary>گزارش مقصدهای صف ({fa(result.jobSummary.completed)} از {fa(result.jobSummary.total)})</summary>{result.destinationResults.map(item=><div key={item.id} className="destination-row"><b>{item.title||item.name}</b> · <span>{labels[item.status]||item.status}</span><p dir="ltr">{item.url}</p>{item.detail&&<p>{item.detail}</p>}{item.finalReputation&&<><p dir="ltr">{item.finalUrl}</p><p>URLhaus مقصد نهایی: {item.finalReputation.message}</p></>}{item.reputation&&<p>URLhaus: {item.reputation.message}</p>}{item.findings?.map((finding,i)=><p key={i}>{finding.title}: {finding.detail}</p>)}</div>)}{result.jobSummary.omitted>0&&<p>{fa(result.jobSummary.omitted)} مقصد به علت سقف فهرست در این صف قرار نگرفت.</p>}</details>}
            <details className="limitations"><summary><Info size={15}/>محدودیت‌های این بررسی</summary><ul>{result.limitations.map((l,i)=><li key={i}>{l}</li>)}<li>GameScam Guard does not upload, hash, inspect, or execute files. Use GTA Guard for file analysis.</li></ul></details>
          </section>}

          <section className="lower-grid"><div className="recent-card"><div className="section-heading"><h2><History size={19}/>بررسی‌های اخیر</h2><button className="text-button" onClick={()=>navigate('history')}>همهٔ بررسی‌ها <ArrowLeft size={15}/></button></div><HistoryTable compact/></div><div className="safety-note"><div className="note-top"><span><Shield size={21}/></span><span className="tiny-label">یادآوری گارد</span></div><h3>هر ماد رایگانی،<br/>به قیمتش نمی‌ارزد.</h3><p>لینک‌های ناشناس می‌توانند حساب بازی یا اطلاعاتت را به خطر بیندازند.</p><button className="text-button" onClick={()=>navigate('resources')}>نشانه‌های یک لینک مشکوک <ArrowUpLeft size={16}/></button></div></section>
          <div className="provider-strip"><span className="provider-caption"><Server size={15}/>پایگاه‌های اطلاعات تهدید</span><span className="provider-brand">URL<span>haus</span></span><button onClick={()=>navigate('settings')} className="provider-status"><i className={health?.providers?.urlhaus?'connected':''}/>{health?.providers?.urlhaus?'اتصال تنظیم شده':'نیازمند کلید دسترسی'}<ChevronLeft size={13}/></button><span className="provider-disclaimer">گزارش نداشتن ≠ امن بودن</span></div>
        </>}

        {page==='history'&&<><PageTitle eyebrow="گزارش‌های شما" title="تاریخچهٔ بررسی‌ها" text="گزارش‌های قبلی را مرور کن و شواهد هر بررسی را دوباره ببین."/><div className="page-card"><div className="history-controls"><div className="search-input"><Search size={18}/><input aria-label="جستجوی تاریخچه" placeholder="جستجوی نام سایت…" value={search} onChange={e=>setSearch(e.target.value)}/></div><select aria-label="فیلتر وضعیت" value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">همهٔ وضعیت‌ها</option><option value="limited">بررسی محدود</option><option value="warning">نیازمند احتیاط</option><option value="danger">تهدید گزارش‌شده</option></select><button className="outline-button" disabled={!history.length} onClick={()=>setModal('clear')}><Trash2 size={16}/>پاک کردن</button></div><HistoryTable/></div><p className="page-footnote"><LockKeyhole size={14}/>تاریخچه فقط در همین مرورگر ذخیره می‌شود. گزارش‌ها نشان‌دهندهٔ وضعیت در زمان بررسی هستند.</p></>}

        {page==='guide'&&<><PageTitle eyebrow="از لینک تا تصمیم" title="گارد چطور کار می‌کند؟" text="پشت هر نتیجه، یک بررسی مشخص و شواهد قابل مشاهده وجود دارد."/><div className="guide-grid">{[{icon:Link2,title:'۱. لینک را وارد می‌کنی',text:'یک آدرس عمومی HTTP یا HTTPS وارد کن. سایت روی سرور بررسی می‌شود و در مرورگر گوشی تو باز نمی‌شود.'},{icon:Globe2,title:'۲. Website content is inspected',text:'We read the title, page text, redirects, forms, and public links. HTTPS alone does not prove a seller is legitimate.'},{icon:Link2,title:'۳. Choose advanced website scanning',text:'With your confirmation, public website destinations are inspected in limited batches. File upload and file execution are not part of this product.'},{icon:ShieldCheck,title:'۴. Review the evidence',text:'The report shows observed page content, redirects, and URLhaus link intelligence when configured.'}].map((s,i)=><article className="guide-card" key={i}><span className="guide-icon"><s.icon size={25}/></span><h3>{s.title}</h3><p>{s.text}</p></article>)}</div><div className="info-banner"><Info size={24}/><div><h3>«بررسی محدود» دقیقاً یعنی چه؟</h3><p>نشانهٔ قطعی تهدید در موارد بررسی‌شده پیدا نشده؛ هویت فروشنده، همهٔ فایل‌ها و رفتار برنامه تأیید نشده‌اند. صفحات نیازمند جاوااسکریپت یا ورود ممکن است کامل دیده نشوند.</p></div></div><button className="primary-button" onClick={()=>navigate('scan')}>یک لینک را بررسی کن <ArrowLeft size={17}/></button></>}

        {page==='resources'&&<><PageTitle eyebrow="راهنمای بازی امن" title="حسابت ارزش محافظت دارد." text="چند نشانهٔ ساده که قبل از دانلود، نصب یا خرید باید بشناسی."/><div className="articles-grid">{[{tag:'خرید امن',icon:Gamepad2,title:'قبل از خرید فایل بازی، فروشنده را بشناس.',text:'نام دامنه را با وب‌سایت رسمی سازنده مقایسه کن. دربارهٔ فروشنده از منابع مستقل تحقیق کن و برای پرداخت، رمز حساب بازی یا کد تأیید را در اختیار فروشنده نگذار.'},{tag:'دانلود آگاهانه',icon:FileSearch,title:'ماد واقعی یا یک فایل خطرناک؟',text:'نام فایل یا آیکون بازی، اصالت آن را ثابت نمی‌کند. منبع انتشار، توضیحات نسخه و تجربهٔ کاربران را بررسی کن. دستور خاموش کردن آنتی‌ویروس یا اجرای فایل با دسترسی مدیر، نیازمند احتیاط است.'},{tag:'امنیت حساب',icon:LockKeyhole,title:'وعدهٔ سکه و جم رایگان را جدی نگیر.',text:'سایت‌هایی که در برابر منابع رایگان رمز ورود یا کد تأیید می‌خواهند ممکن است فیشینگ باشند. تأیید دومرحله‌ای را فعال کن و برای هر سرویس رمز جداگانه داشته باش.'},{tag:'شناخت لینک',icon:Link2,title:'قفل کنار آدرس، تضمین اعتماد نیست.',text:'HTTPS ارتباط را رمزگذاری می‌کند؛ یک سایت کلاهبرداری هم می‌تواند گواهی معتبر داشته باشد. حروف مشابه در دامنه، انتقال به آدرس دیگر و پرداخت خارج از فروشگاه را بررسی کن.'}].map((article,i)=><article className="article-card" key={i}><div className="article-top"><span className="guide-icon"><article.icon size={24}/></span><span className="article-tag">{article.tag}</span></div><h3>{article.title}</h3><p>{article.text}</p></article>)}</div><div className="info-banner"><ShieldCheck size={26}/><div><h3>یک بررسی، قبل از هر تصمیم</h3><p>وقتی دربارهٔ لینکی مطمئن نیستی، شواهد آن را با گارد بررسی کن.</p></div><button className="primary-button" onClick={()=>navigate('scan')}>بررسی لینک <ArrowLeft size={17}/></button></div></>}

        {page==='settings'&&<><PageTitle eyebrow="فضای شخصی شما" title="تنظیمات گارد" text="وضعیت سرویس و نحوهٔ نگهداری گزارش‌ها را اینجا مدیریت کن."/><div className="settings-grid"><section className="page-card settings-card"><h2><Server size={19}/>اتصال به پایگاه‌های تهدید</h2><p className="settings-desc">کلیدها فقط روی سرور نگهداری می‌شوند و وارد مرورگر نمی‌شوند.</p><div className="setting-row"><div><b>URLhaus</b><small>Threat intelligence lookup for website links</small></div><span className={`connection-badge ${health?.providers?.urlhaus?'connected':''}`}>{health?.providers?.urlhaus?'Key configured':'Not connected'}</span></div><div className="config-info"><Info size={18}/><p>To enable this, the site administrator must set the abuse.ch key in <code dir="ltr">ABUSECH_AUTH_KEY</code> on the server. Each URLhaus response is shown in the report.</p></div><a className="text-button" href="https://auth.abuse.ch/" target="_blank" rel="noopener noreferrer">دریافت کلید از abuse.ch <ExternalLink size={15}/></a></section><section className="page-card settings-card"><h2><LockKeyhole size={19}/>حریم خصوصی و تاریخچه</h2><div className="setting-row"><div><b>ذخیرهٔ تاریخچه در این مرورگر</b><small>تا ۳۰ گزارش اخیر برای مرور مجدد</small></div><button role="switch" aria-checked={saveHistory} aria-label="ذخیره تاریخچه" className={`toggle ${saveHistory?'on':''}`} onClick={()=>setSaveHistory(!saveHistory)}><span/></button></div><p className="settings-desc">Links are sent to the server for inspection. Scan data is kept in server memory for up to 30 minutes. GameScam Guard does not accept or execute files. Do not enter private links.</p><button className="outline-button" disabled={!history.length} onClick={()=>setModal('clear')}><Trash2 size={16}/>پاک کردن تاریخچه</button></section></div><div className="info-banner"><FileSearch size={23}/><div><h3>محدودهٔ بررسی فعلی</h3><p>Public HTML retrieval and website evidence · bounded queue of public page destinations · no file upload, file hashing, or file execution</p></div></div></>}
        <footer className="footer"><span><ShieldCheck size={14}/>گیم‌اسکم گارد؛ همراه بازی‌های امن‌تر.</span><span>با آگاهی کلیک کن <span className="footer-dot">·</span> نسخهٔ ۱.۰</span></footer>
      </main>
    </div>

    {toast&&<div className="toast" role="status"><Check size={18}/>{toast}<button aria-label="بستن پیام" onClick={()=>setToast('')}><X size={15}/></button></div>}
    {modal==='account'?<AccountDialog modalRef={modalRef} state={accountState} account={account} googleEnabled={googleEnabled} googleSignup={googleSignup} onClose={()=>{setGoogleSignup('');setModal(null);}} onRetry={()=>setAccountRetry(value=>value+1)} onSignedIn={user=>{localStorage.setItem('guard-account-session',user.sessionToken);setGoogleSignup('');setAccount(user);setModal(null);}} onSignOut={()=>{localStorage.removeItem('guard-account-session');setAccount(null);setModal(null);}}/>:modal&&<div className="modal-backdrop" onClick={()=>setModal(null)}><div ref={modalRef} className="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title" onClick={e=>e.stopPropagation()}><button className="icon-button modal-close" aria-label="بستن" onClick={()=>setModal(null)}><X size={20}/></button><span className="modal-icon">{modal==='advanced'?<Globe2 size={29}/>:modal==='clear'?<Trash2 size={28}/>:modal==='notifications'?<Bell size={28}/>:<CircleHelp size={28}/>}</span><h2 id="modal-title">{modal==='advanced'?'Scan linked public pages?':modal==='clear'?'تاریخچه پاک شود؟':modal==='notifications'?'اعلان‌های گارد':'چطور شروع کنم؟'}</h2>{modal==='advanced'?<><p>With your confirmation, public website destinations found in this report are inspected in bounded batches.</p><div className="modal-note"><Info size={17}/>GameScam Guard does not download, upload, hash, analyze, or execute files. Pages that require sign-in or payment are not opened.</div><div className="modal-actions"><button className="primary-button" onClick={runAdvanced}>Scan public pages <ArrowLeft size={17}/></button><button className="outline-button" onClick={()=>setModal(null)}>Not now</button></div></>:modal==='clear'?<><p>گزارش‌های ذخیره‌شده در این مرورگر حذف می‌شوند. این کار قابل بازگشت نیست.</p><div className="modal-actions"><button className="primary-button" disabled={busy||advancedBusy} onClick={()=>{setHistory([]);setResult(null);setPendingJob(null);localStorage.removeItem('guard-pending-job');setModal(null);setToast('تاریخچه پاک شد.');}}>پاک کردن تاریخچه</button><button className="outline-button" onClick={()=>setModal(null)}>انصراف</button></div></>:modal==='notifications'?<><p>{result?'آخرین بررسی آماده است. نتیجه و شواهد را در گزارش ببین.':'هنوز اعلانی نداری. وقتی بررسی لینک تمام شود، نتیجه همین‌جا نمایش داده می‌شود.'}</p>{result&&<button className="primary-button" onClick={()=>{setModal(null);navigate('scan');setTimeout(()=>reportRef.current?.scrollIntoView({behavior:'smooth'}),100);}}>دیدن آخرین گزارش <ArrowLeft size={15}/></button>}</>:<><p>لینک عمومی سایت بازی یا فروشگاه را کپی کن، در کادر لینک بچسبان و «شروع بررسی» را بزن. گزارش شامل محتوای عمومی و لینک‌های صفحه است.</p><div className="modal-note"><Info size={17}/>برای بررسی عمیق‌تر، می‌توانی بررسی صفحه‌های عمومی مرتبط را انتخاب کنی. نتیجهٔ محدود، تضمین امنیت نیست.</div><button className="primary-button" onClick={()=>{setModal(null);navigate('guide');}}>راهنمای کامل <ArrowLeft size={17}/></button></>}</div></div>}
  </div>;
}

function PasswordStrength({value}){const rules=[['length',value.length>=10,'At least 10 characters'],['upper',/[A-Z]/.test(value),'One uppercase letter'],['lower',/[a-z]/.test(value),'One lowercase letter'],['number',/\d/.test(value),'One number']];const score=rules.filter(([,valid])=>valid).length;const label=['','Weak','Fair','Good','Strong'][score];return <div className={`password-strength ${['','weak','weak','fair','good'][score]}`} aria-live="polite"><div className="password-meter"><i style={{width:`${score*25}%`}}/></div><b>{value?label:'Choose a password'}</b><ul>{rules.map(([id,valid,text])=><li className={valid?'valid':''} key={id}><Check size={13}/>{text}</li>)}</ul></div>;}

function GoogleButton(){return <><button type="button" className="google-button" onClick={()=>window.location.assign(apiUrl('auth/google/start'))}><b aria-hidden="true">G</b>Sign up or sign in with Google</button><div className="social-divider"><span/>or<span/></div></>}

function AccountDialog({modalRef,state,account,googleEnabled,googleSignup,onClose,onRetry,onSignedIn,onSignOut}){
  const [mode,setMode]=useState('signup');
  const [stage,setStage]=useState('details');
  const [form,setForm]=useState({firstName:'',lastName:'',birthDate:'',username:'',email:'',password:'',confirmPassword:''});
  const [code,setCode]=useState('');
  const [attempt,setAttempt]=useState(null);
  const [busy,setBusy]=useState(false);
  const [error,setError]=useState('');
  const [availability,setAvailability]=useState({email:'',username:''});
  const [checkingAvailability,setCheckingAvailability]=useState(false);
  const minimumBirthDate=(()=>{const value=new Date();value.setFullYear(value.getFullYear()-12);return value.toISOString().slice(0,10);})();
  const suggestion=[form.firstName,form.lastName].map(value=>value.trim().replace(/[^\p{L}\p{N}]+/gu,'_').replace(/^_+|_+$/g,'')).filter(Boolean).join('_')||'Player_Guard';
  const update=(field,value)=>{setForm(current=>({...current,[field]:value}));if(field==='email'||field==='username')setAvailability(current=>({...current,[field]:''}));};
  const availabilityText=field=>({available:field==='email'?'This email is available.':'This username is available.',taken:field==='email'?'This email is already registered. Sign in instead.':'This username is already taken. Choose another one.',invalid:field==='email'?'Enter a valid email address.':'Use 3–48 letters, numbers, spaces, _ or -.'}[availability[field]]||'');
  function switchMode(next){setMode(next);setStage('details');setCode('');setAttempt(null);setError('');setAvailability({email:'',username:''});}
  async function checkAvailability(){if(busy||!form.email.trim()&&!form.username.trim())return;setCheckingAvailability(true);try{setAvailability(await checkAccountAvailability({email:form.email.trim(),username:form.username.trim()}));}catch{setAvailability({email:'',username:''});}finally{setCheckingAvailability(false);}}
  async function submitSignup(event){event.preventDefault();if(busy)return;if(form.password!==form.confirmPassword){setError('Passwords do not match.');return;}setBusy(true);setError('');try{const next=await sendEmailCode({email:form.email.trim(),profile:{firstName:form.firstName,lastName:form.lastName,birthDate:form.birthDate,username:form.username,password:form.password}});setAttempt(next);setStage('code');}catch(err){setError(err.message||'We could not send a code to that email address.');}finally{setBusy(false);}}
  async function submitPassword(event){event.preventDefault();if(busy)return;setBusy(true);setError('');try{const session=await signInWithPassword({email:form.email.trim(),password:form.password});const profile=await readEmailSession(session.sessionToken);onSignedIn({...profile,sessionToken:session.sessionToken});}catch(err){setError(err.message||'Email or password is not correct.');}finally{setBusy(false);}}
  async function requestCodeLogin(){if(busy||!form.email.trim())return;setBusy(true);setError('');try{setAttempt(await sendEmailCode({email:form.email.trim()}));setMode('code');setStage('code');}catch(err){setError(err.message||'We could not send a code to that email address.');}finally{setBusy(false);}}
  async function submitCode(event){event.preventDefault();if(!attempt||busy)return;setBusy(true);setError('');try{const session=await verifyEmailCode({verificationToken:attempt.verificationToken,code});const profile=await readEmailSession(session.sessionToken);onSignedIn({...profile,sessionToken:session.sessionToken});}catch(err){setError(err.message||'That code is not valid. Request a new one and try again.');}finally{setBusy(false);}}
  async function resend(){if(busy)return;setBusy(true);setError('');try{setAttempt(await sendEmailCode(mode==='signup'?{email:form.email.trim(),profile:{firstName:form.firstName,lastName:form.lastName,birthDate:form.birthDate,username:form.username,password:form.password}}:{email:form.email.trim()}));}catch(err){setError(err.message||'We could not resend the code yet. Please wait and try again.');}finally{setBusy(false);}}
  async function submitGoogleSignup(event){event.preventDefault();if(busy)return;setBusy(true);setError('');try{const session=await completeGoogleSignup({signupToken:googleSignup,profile:{firstName:form.firstName,lastName:form.lastName,birthDate:form.birthDate,username:form.username}});const profile=await readEmailSession(session.sessionToken);onSignedIn({...profile,sessionToken:session.sessionToken});}catch(err){setError(err.message||'Google sign-up could not be completed.');}finally{setBusy(false);}}
  const duplicate=/already (registered|taken)|just registered/i.test(error);
  if(!account&&state==='unavailable')return <div className="modal-backdrop" onClick={onClose}><section ref={modalRef} className="account-modal" role="dialog" aria-modal="true" aria-labelledby="account-title" onClick={event=>event.stopPropagation()}><button className="icon-button modal-close" aria-label="Close" onClick={onClose}><X size={20}/></button><h2 id="account-title">Account service is unavailable</h2><p>We could not reach the account service. Google or the account API may be blocked on this connection. Try again after checking your connection.</p><button className="primary-button account-wide" onClick={onRetry}>Try again</button></section></div>;
  const signup=<form onSubmit={submitSignup}><div className="account-heading"><span className="account-shield"><ShieldCheck size={22}/></span><h2 id="account-title">Create your account</h2><p>Complete your profile, choose a password, then confirm your email.</p></div>{googleEnabled&&<GoogleButton/>}<div className="account-two-columns"><label>First name<input autoFocus autoComplete="given-name" required maxLength="80" value={form.firstName} onChange={event=>update('firstName',event.target.value)} placeholder="For example: Alex"/><small>Example: Alex</small></label><label>Last name<input autoComplete="family-name" required maxLength="80" value={form.lastName} onChange={event=>update('lastName',event.target.value)} placeholder="For example: Morgan"/><small>Example: Morgan</small></label></div><label className="date-field">Date of birth<input type="date" autoComplete="bday" max={minimumBirthDate} required value={form.birthDate} onChange={event=>update('birthDate',event.target.value)}/><small>Example: 2000-01-01 · you must be at least 12.</small></label><label>Username<div className="field-with-action"><input autoComplete="username" minLength="3" maxLength="48" required value={form.username} onChange={event=>update('username',event.target.value)} onBlur={checkAvailability} placeholder="For example: Player_Guard"/><button type="button" className="username-suggestion" onClick={()=>update('username',suggestion)}>Use suggestion</button></div><small>Choose it yourself. Example: <b dir="ltr">{suggestion}</b></small><span className={'availability '+availability.username}>{checkingAvailability?'Checking…':availabilityText('username')}</span></label><label>Email address<input autoComplete="email" inputMode="email" type="email" required value={form.email} onChange={event=>update('email',event.target.value)} onBlur={checkAvailability} placeholder="For example: you@example.com"/><small>Example: you@example.com</small><span className={'availability '+availability.email}>{checkingAvailability?'Checking…':availabilityText('email')}</span></label><label>Password<input autoComplete="new-password" type="password" minLength="10" maxLength="128" required value={form.password} onChange={event=>update('password',event.target.value)} placeholder="At least 10 characters"/></label><PasswordStrength value={form.password}/><label>Confirm password<input autoComplete="new-password" type="password" required value={form.confirmPassword} onChange={event=>update('confirmPassword',event.target.value)} placeholder="Type the password again"/></label>{error&&<div className="account-error" role="alert">{error}{duplicate&&<button type="button" onClick={()=>switchMode('signin')}>Sign in</button>}</div>}<button className="primary-button account-wide" disabled={busy||availability.email==='taken'||availability.username==='taken'}>{busy?<LoaderCircle className="spin" size={17}/>:null}Send verification code <ArrowLeft size={16}/></button><p className="account-switch">Already have an account? <button type="button" onClick={()=>switchMode('signin')}>Sign in</button></p></form>;
  const codeForm=<form onSubmit={submitCode}><div className="account-heading"><span className="account-shield"><ShieldCheck size={22}/></span><h2 id="account-title">Enter your code</h2><p>We sent a six-digit code to <b dir="ltr">{form.email}</b>.</p></div><label>Verification code<input className="code-input" autoComplete="one-time-code" inputMode="numeric" pattern="[0-9]{6}" maxLength="6" required autoFocus value={code} onChange={event=>setCode(event.target.value.replace(/\D/g,''))} placeholder="000000"/></label>{error&&<p className="account-error" role="alert">{error}</p>}<button className="primary-button account-wide" disabled={busy||code.length!==6}>{busy?<LoaderCircle className="spin" size={17}/>:null}Verify and continue <ArrowLeft size={16}/></button><button type="button" className="text-button account-wide" disabled={busy} onClick={resend}>Send a new code</button><button type="button" className="text-button account-wide" onClick={()=>switchMode('signup')}>Use another method</button></form>;
  const googleForm=<form onSubmit={submitGoogleSignup}><div className="account-heading"><span className="account-shield"><ShieldCheck size={22}/></span><h2 id="account-title">Finish your Google account</h2><p>Your Google email is verified. Complete these details once to create your GameScam Guard account.</p></div><div className="account-two-columns"><label>First name<input autoFocus autoComplete="given-name" required maxLength="80" value={form.firstName} onChange={event=>update('firstName',event.target.value)} placeholder="For example: Alex"/></label><label>Last name<input autoComplete="family-name" required maxLength="80" value={form.lastName} onChange={event=>update('lastName',event.target.value)} placeholder="For example: Morgan"/></label></div><label className="date-field">Date of birth<input type="date" autoComplete="bday" max={minimumBirthDate} required value={form.birthDate} onChange={event=>update('birthDate',event.target.value)}/><small>You must be at least 12.</small></label><label>Username<div className="field-with-action"><input autoComplete="username" minLength="3" maxLength="48" required value={form.username} onChange={event=>update('username',event.target.value)} onBlur={checkAvailability} placeholder="For example: Player_Guard"/><button type="button" className="username-suggestion" onClick={()=>update('username',suggestion)}>Use suggestion</button></div><span className={'availability '+availability.username}>{checkingAvailability?'Checking…':availabilityText('username')}</span></label>{error&&<p className="account-error" role="alert">{error}</p>}<button className="primary-button account-wide" disabled={busy||availability.username==='taken'}>{busy?<LoaderCircle className="spin" size={17}/>:null}Create account with Google <ArrowLeft size={16}/></button></form>;
  const signin=<form onSubmit={submitPassword}><div className="account-heading"><span className="account-shield"><ShieldCheck size={22}/></span><h2 id="account-title">Welcome back</h2><p>Sign in with the email and password you chose.</p></div>{googleEnabled&&<GoogleButton/>}<label>Email address<input autoFocus autoComplete="email" inputMode="email" type="email" required value={form.email} onChange={event=>update('email',event.target.value)} placeholder="Enter your email address"/></label><label>Password<input autoComplete="current-password" type="password" required value={form.password} onChange={event=>update('password',event.target.value)} placeholder="Enter your password"/></label>{error&&<p className="account-error" role="alert">{error}</p>}<button className="primary-button account-wide" disabled={busy}>{busy?<LoaderCircle className="spin" size={17}/>:null}Sign in <ArrowLeft size={16}/></button><button type="button" className="text-button account-wide" disabled={busy} onClick={requestCodeLogin}>Use an email code instead</button><p className="account-switch">New to GameScam Guard? <button type="button" onClick={()=>switchMode('signup')}>Create an account</button></p></form>;
  return <div className="modal-backdrop" onClick={onClose}><section ref={modalRef} className="account-modal account-signup-card" role="dialog" aria-modal="true" aria-labelledby="account-title" onClick={event=>event.stopPropagation()}><button className="icon-button modal-close" aria-label="Close" onClick={onClose}><X size={20}/></button>{account?<><span className="modal-icon"><ShieldCheck size={29}/></span><h2 id="account-title">You are signed in</h2><p>{account.firstName||account.username} · {account.email}</p><button className="outline-button account-wide" onClick={onSignOut}>Sign out</button></>:state==='loading'?<p className="account-loading"><LoaderCircle size={18}/>Preparing secure sign-in…</p>:googleSignup?googleForm:stage==='code'?codeForm:mode==='signup'?signup:signin}</section></div>;
}

function PageTitle({eyebrow,title,text}) { return <section className="page-title"><div className="eyebrow"><span/>{eyebrow}</div><h1>{title}</h1><p>{text}</p></section>; }
createRoot(document.getElementById('root')).render(<App/>);
